<?php $hasProducts=$metrics['total_products']>0;$hasLogo=(bool)($store['logo_path']??null);$isActive=$store['status']==='ACTIVE';$isSuspended=$store['status']==='SUSPENDED';$completed=3+($hasProducts?1:0)+($hasLogo?1:0)+($isActive?1:0);$progress=(int)round($completed/6*100); ?>
<section><div class="page-heading"><div><p class="eyebrow">Merchant dashboard</p><h1>Good to see you, <?= e(explode(' ',$user['name'])[0]) ?></h1><p class="muted">Here is the current state of <?= e($store['name']) ?>.</p></div><span class="badge <?= strtolower($store['status']) ?>"><?= e($store['status']) ?></span></div>
<div class="dashboard-metrics"><article><span>Orders today</span><strong><?= e($metrics['orders_today']) ?></strong><small>Excludes cancelled orders</small></article><article><span>Order value today</span><strong><?= e($store['currency_code']) ?> <?= e($metrics['order_value_today']) ?></strong><small>Saved order totals</small></article><article><span>Total products</span><strong><?= e($metrics['total_products']) ?></strong><small>Saved catalog items</small></article><article><span>Available</span><strong><?= e($metrics['available_products']) ?></strong><small><?= e($metrics['unavailable_products']) ?> unavailable</small></article></div>
<div class="dashboard-columns"><section class="setup-card"><div><strong>Store setup — <?= e($progress) ?>%</strong><div class="meter"><span style="width:<?= e($progress) ?>%"></span></div></div><ul><li class="done">Account created</li><li class="done">Business created</li><li class="done">WhatsApp connected</li><li class="<?= $hasProducts?'done':'' ?>"><?= $hasProducts?'First product added':'Add first product' ?></li><li class="<?= $hasLogo?'done':'' ?>"><?= $hasLogo?'Logo added':'Add logo' ?></li><li class="<?= $isActive?'done':'' ?>"><?= $isActive?'Store published':'Publish store' ?></li></ul><div class="setup-actions"><?php if(!$hasProducts):?><a class="button primary" href="/products/create">Add first product</a><?php elseif(!$hasLogo):?><a class="button primary" href="/merchant/design">Customize store</a><?php endif ?></div></section>
<section class="panel recent-panel"><div class="panel-title"><h2>Recent orders</h2><a href="/merchant/orders">View all</a></div><?php if(!$recentOrders):?><div class="empty-inline">Your first order will appear here.</div><?php else:?><div class="recent-orders"><?php foreach($recentOrders as$order):?><a href="/merchant/orders/<?= e($order['reference']) ?>"><span><strong><?= e($order['reference']) ?></strong><small><?= e($order['customer_name']) ?></small></span><span><strong><?= e($order['currency_code']) ?> <?= e($order['total']) ?></strong><small><?= e(ucfirst(strtolower($order['status']))) ?></small></span></a><?php endforeach ?></div><?php endif ?></section></div>
<section class="panel low-stock-panel"><div class="panel-title"><h2>Low stock<?= $lowStock?' <span class="count-badge">'.count($lowStock).'</span>':'' ?></h2><form method="post" action="/merchant/low-stock-threshold" class="low-stock-threshold-form"><?= csrf_field() ?><label>Alert at ≤<input type="number" name="low_stock_threshold" value="<?= e($store['low_stock_threshold']) ?>" min="0" max="100000"></label><button class="button compact secondary" type="submit">Save</button></form></div><?php if(!$lowStock):?><div class="empty-inline">No variants are at or below your threshold right now.</div><?php else:?><div class="low-stock-list"><?php foreach($lowStock as$item):?><a href="/products/<?= e($item['product_id']) ?>/edit"><span><strong><?= e($item['product_name']) ?></strong><small><?= e($item['label']) ?></small></span><span class="badge <?= (int)$item['stock_quantity']===0?'danger':'archived' ?>"><?= (int)$item['stock_quantity']===0?'Out of stock':e($item['stock_quantity']).' left' ?></span></a><?php endforeach ?></div><?php endif ?></section>
<section class="store-status-card"><div><span class="status-dot"></span><strong>Store status: <?= e($store['status']) ?></strong><p><?php if($isSuspended):?>Publishing controls are unavailable while the platform has suspended this store.<?php elseif($isActive):?>Your public storefront is live at /<?= e($store['slug']) ?>.<?php elseif($metrics['public_ready_products']>0):?>Your catalog is ready to publish.<?php else:?>Add an active, available product before publishing.<?php endif ?></p></div><div class="store-status-actions"><?php if($isSuspended):?><a class="button secondary" href="/products">Manage products</a><?php elseif($isActive):?><a class="button secondary" href="/<?= e($store['slug']) ?>">Open storefront</a><a class="button secondary" href="/merchant/design">Store design</a><form method="post" action="/storefront/unpublish" data-confirm="Make store private?" data-confirm-message="Customers will no longer be able to open the storefront until you publish it again."><?= csrf_field() ?><button class="button secondary" type="submit">Unpublish</button></form><?php else:?><form method="post" action="/storefront/publish"><?= csrf_field() ?><button class="button primary" type="submit" <?= $metrics['public_ready_products']<1?'disabled':'' ?>>Publish storefront</button></form><a class="button secondary" href="/merchant/design">Store design</a><a class="button secondary" href="/products">Manage products</a><?php endif ?></div></section></section>
